"""Engine-owned LLM MT via OpenAI-compatible llama-server (/v1/chat/completions).

Used for free 推理翻译 (Sakura / GalTransl-style line-aligned JA→ZH) when mtBackend=llama.
Smart translate (Pro) stays on mtBackend=external → desktop adapter.
"""
from __future__ import annotations

import logging
import re
from typing import Any, Callable
from urllib.parse import urlparse

import httpx

ProgressCb = Callable[[dict[str, Any]], None]
CancelCheck = Callable[[], None]

_log = logging.getLogger("transub_engine.mt.llama")

DEFAULT_TIMEOUT_SEC = 600.0
DEFAULT_BATCH_SIZE = 8
DEFAULT_TEMPERATURE = 0.1
DEFAULT_TOP_P = 0.9

DEFAULT_SYSTEM_PROMPT = (
    "你是一个日译中字幕翻译模型，译文需通顺自然口语化，避免翻译腔。"
    "联系上下文正确使用人称代词；仅在上下文明确时补「我/你」及已出现称呼，全局一致。"
    "不擅自添加原文中没有的代词、人名、称呼或旁白。"
    "专有名词仅使用原文已出现的写法或术语表译名；禁止臆造角色名。"
    "严禁添加原文未出现的常见臆造人名（如佳奈、舞、玲奈、真理、斗碧等），尤其不要在句末乱贴人名。"
    "每行只输出对应那一行的译文，禁止把多行挤进一行，禁止无意义叠词循环。"
    "原文仅为纯语气/拟声时可译为对应短语气词；有完整语义时须译全句，句末语气词可保留。"
)


class MtLlamaError(RuntimeError):
    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


def normalize_mt_llama(cfg: Any) -> dict[str, Any]:
    if cfg is None:
        raise MtLlamaError("MT_LLAMA_CONFIG", "mtLlama is required when mtBackend=llama")
    if not isinstance(cfg, dict):
        raise MtLlamaError("MT_LLAMA_CONFIG", "mtLlama must be an object")

    base_url = str(cfg.get("baseUrl") or cfg.get("base_url") or "").strip().rstrip("/")
    ensure = cfg.get("ensure")
    if ensure is not None and not isinstance(ensure, dict):
        raise MtLlamaError("MT_LLAMA_CONFIG", "mtLlama.ensure must be an object")

    timeout_raw = cfg.get("timeoutSec", cfg.get("timeout_sec", DEFAULT_TIMEOUT_SEC))
    try:
        timeout_sec = float(timeout_raw)
    except (TypeError, ValueError) as err:
        raise MtLlamaError("MT_LLAMA_CONFIG", "mtLlama.timeoutSec must be a number") from err
    if timeout_sec <= 0:
        raise MtLlamaError("MT_LLAMA_CONFIG", "mtLlama.timeoutSec must be > 0")

    batch_raw = cfg.get("batchSize", cfg.get("batch_size", DEFAULT_BATCH_SIZE))
    try:
        batch_size = int(batch_raw)
    except (TypeError, ValueError) as err:
        raise MtLlamaError("MT_LLAMA_CONFIG", "mtLlama.batchSize must be an integer") from err
    if batch_size < 1:
        raise MtLlamaError("MT_LLAMA_CONFIG", "mtLlama.batchSize must be >= 1")
    batch_size = min(40, batch_size)

    model = str(cfg.get("model") or cfg.get("modelId") or "local").strip() or "local"
    api_key = str(cfg.get("apiKey") or cfg.get("api_key") or "local").strip() or "local"
    system_prompt = str(cfg.get("systemPrompt") or cfg.get("system_prompt") or "").strip()
    if not system_prompt:
        system_prompt = DEFAULT_SYSTEM_PROMPT

    temperature = cfg.get("temperature", DEFAULT_TEMPERATURE)
    try:
        temperature = float(temperature)
    except (TypeError, ValueError):
        temperature = DEFAULT_TEMPERATURE

    top_p = cfg.get("topP", cfg.get("top_p", DEFAULT_TOP_P))
    try:
        top_p = float(top_p)
    except (TypeError, ValueError):
        top_p = DEFAULT_TOP_P

    return {
        "baseUrl": base_url,
        "ensure": dict(ensure) if isinstance(ensure, dict) else None,
        "timeoutSec": timeout_sec,
        "batchSize": batch_size,
        "model": model,
        "apiKey": api_key,
        "systemPrompt": system_prompt,
        "temperature": temperature,
        "topP": top_p,
        "glossary": cfg.get("glossary") if isinstance(cfg.get("glossary"), list) else [],
    }


def _estimate_max_tokens(cues: list[dict[str, Any]]) -> int:
    chars = sum(len(str(c.get("text") or "")) for c in cues)
    n = len(cues)
    est = int(chars * 2.2) + (n * 8) + 48
    floor = min(768, 128 + (n * 64)) if n >= 4 else 64
    return max(floor, min(1024, est))


def _format_glossary_block(pairs: list[Any], *, max_terms: int = 40) -> str:
    lines: list[str] = []
    for item in pairs or []:
        if not isinstance(item, dict):
            continue
        src = str(item.get("src") or item.get("source") or "").strip()
        tgt = str(item.get("tgt") or item.get("target") or item.get("canonical") or "").strip()
        if not src or not tgt or src == tgt:
            continue
        lines.append(f"{src} -> {tgt}")
        if len(lines) >= max_terms:
            break
    return "\n".join(lines)


def _build_messages(
    batch: list[dict[str, Any]],
    *,
    system_prompt: str,
    glossary_pairs: list[Any],
) -> list[dict[str, str]]:
    joined = "\n".join(str(c.get("text") or "") for c in batch)
    glossary = _format_glossary_block(glossary_pairs)
    line_rule = (
        f"共 {len(batch)} 行。只输出译文，每行对应原文一行，不要编号、不要解释、不要空行、不要额外内容。"
        "原文仅为纯语气/拟声时可短译；对白有完整语义时禁止只输出语气词（嗯/啊/请等），须译出完整意思。"
    )
    if glossary:
        user = (
            f"根据以下术语表（可以为空）：\n{glossary}\n"
            f"将下面的日文文本根据对应关系和备注翻译成中文。{line_rule}\n{joined}"
        )
    else:
        user = f"将下面的日文文本翻译成中文。{line_rule}\n{joined}"
    return [
        {"role": "system", "content": system_prompt},
        {"role": "user", "content": user},
    ]


def _parse_line_aligned(content: str, expected: list[dict[str, Any]]) -> list[str]:
    raw = str(content or "").replace("\r\n", "\n").strip()
    if not raw:
        raise MtLlamaError("MT_LLAMA_RESPONSE", "模型返回为空")
    text = raw
    fence = re.match(r"^```(?:\w+)?\n([\s\S]*?)```$", text)
    if fence:
        text = fence.group(1).strip()
    lines = [ln.rstrip() for ln in text.split("\n")]
    while lines and not lines[0].strip():
        lines.pop(0)
    while lines and not lines[-1].strip():
        lines.pop()
    if len(lines) == 1 and len(expected) > 1:
        parts = [p.strip() for p in re.split(r"\s*[|｜]\s*", lines[0]) if p.strip()]
        if len(parts) == len(expected):
            lines = parts
    if len(lines) < len(expected):
        lines.extend([""] * (len(expected) - len(lines)))
    elif len(lines) > len(expected):
        lines = lines[: len(expected)]
    return [str(x).strip() for x in lines]


def _resolve_chat_base(cfg: dict[str, Any]) -> str:
    base = str(cfg.get("baseUrl") or "").strip().rstrip("/")
    if base:
        return base
    from ..llama_server import MANAGER

    health = MANAGER.health()
    if health.get("healthy") and health.get("baseUrl"):
        return str(health["baseUrl"]).rstrip("/") + "/v1"
    raise MtLlamaError(
        "MT_LLAMA_NOT_RUNNING",
        "llama-server 未运行，且未提供 mtLlama.baseUrl / ensure",
    )


def _ensure_llama(cfg: dict[str, Any]) -> None:
    ensure = cfg.get("ensure")
    if not isinstance(ensure, dict) or not ensure:
        return
    from ..llama_server import MANAGER

    body = dict(ensure)
    # Job already released ASR VRAM just before MT; still allow explicit afterAsr.
    result = MANAGER.ensure(body)
    if not result.get("ok"):
        raise MtLlamaError(
            str(result.get("code") or "MT_LLAMA_ENSURE_FAILED"),
            str(result.get("error") or "启动 llama-server 失败"),
        )
    if not cfg.get("baseUrl"):
        port = result.get("port")
        if port:
            cfg["baseUrl"] = f"http://127.0.0.1:{int(port)}/v1"


def _ensure_llama_with_heartbeat(
    cfg: dict[str, Any],
    *,
    on_progress: ProgressCb | None = None,
    cancel_check: CancelCheck | None = None,
) -> None:
    """Run ensure(); emit load-band heartbeats so the UI does not freeze at 66%."""
    import threading

    ensure = cfg.get("ensure")
    if not isinstance(ensure, dict) or not ensure:
        _ensure_llama(cfg)
        return

    err_box: list[BaseException] = []

    def _run() -> None:
        try:
            _ensure_llama(cfg)
        except BaseException as exc:  # noqa: BLE001 — re-raised below
            err_box.append(exc)

    thread = threading.Thread(target=_run, daemon=True, name="mt-llama-ensure")
    thread.start()
    ticks = 0
    while thread.is_alive():
        thread.join(timeout=2.0)
        if not thread.is_alive():
            break
        if cancel_check:
            cancel_check()
        ticks += 1
        if on_progress:
            # Local 1–7 stays in remap load band (overall ~65–70).
            try:
                on_progress(
                    {
                        "stage": "translate",
                        "percent": min(7, 1 + ticks),
                        "detail": f"正在加载翻译模型… {ticks * 2}s",
                    }
                )
            except Exception:
                pass
    if err_box:
        raise err_box[0]


def _chat_completion(
    *,
    client: httpx.Client,
    base_url: str,
    api_key: str,
    model: str,
    messages: list[dict[str, str]],
    max_tokens: int,
    temperature: float,
    top_p: float,
) -> str:
    root = base_url.rstrip("/")
    if root.endswith("/v1"):
        url = f"{root}/chat/completions"
    else:
        url = f"{root}/v1/chat/completions"
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {api_key}",
    }
    payload = {
        "model": model,
        "messages": messages,
        "temperature": temperature,
        "top_p": top_p,
        "max_tokens": max_tokens,
        "stream": False,
    }
    try:
        resp = client.post(url, headers=headers, json=payload)
    except httpx.TimeoutException as err:
        raise MtLlamaError("MT_LLAMA_TIMEOUT", f"llama chat timeout: {err}") from err
    except httpx.HTTPError as err:
        raise MtLlamaError("MT_LLAMA_HTTP", f"llama chat failed: {err}") from err
    if resp.status_code >= 400:
        detail = (resp.text or "")[:400]
        raise MtLlamaError(
            "MT_LLAMA_HTTP",
            f"llama chat HTTP {resp.status_code}: {detail}",
        )
    try:
        data = resp.json()
    except Exception as err:
        raise MtLlamaError("MT_LLAMA_RESPONSE", "llama chat response is not JSON") from err
    choices = data.get("choices") if isinstance(data, dict) else None
    if not isinstance(choices, list) or not choices:
        raise MtLlamaError("MT_LLAMA_RESPONSE", "llama chat missing choices")
    msg = choices[0].get("message") if isinstance(choices[0], dict) else None
    content = msg.get("content") if isinstance(msg, dict) else None
    return str(content or "")


def llama_translate_cues(
    cues: list[dict[str, Any]],
    *,
    mt_llama: dict[str, Any] | None,
    language: str = "ja",
    target_language: str = "zh",
    job_id: str | None = None,
    on_progress: ProgressCb | None = None,
    cancel_check: CancelCheck | None = None,
) -> list[dict[str, Any]]:
    _ = (language, target_language, job_id)
    cfg = normalize_mt_llama(mt_llama)
    if on_progress:
        try:
            on_progress(
                {
                    "stage": "translate",
                    "percent": 1,
                    "detail": "正在启动 llama-server…",
                }
            )
        except Exception:
            pass
    _ensure_llama_with_heartbeat(cfg, on_progress=on_progress, cancel_check=cancel_check)
    base_url = _resolve_chat_base(cfg)

    parsed = urlparse(base_url if "://" in base_url else f"http://{base_url}")
    if parsed.scheme not in ("http", "https") or not parsed.netloc:
        raise MtLlamaError("MT_LLAMA_CONFIG", f"mtLlama.baseUrl is invalid: {base_url}")

    total = len(cues)
    batch_size = int(cfg["batchSize"])
    out: list[dict[str, Any]] = []
    if on_progress:
        try:
            on_progress(
                {
                    "stage": "translate",
                    "percent": 8,
                    "detail": f"模型已就绪，开始翻译（{total} 条）…",
                }
            )
        except Exception:
            pass

    with httpx.Client(timeout=httpx.Timeout(cfg["timeoutSec"])) as client:
        for start in range(0, total, batch_size):
            if cancel_check:
                cancel_check()
            batch = cues[start : start + batch_size]
            messages = _build_messages(
                batch,
                system_prompt=str(cfg["systemPrompt"]),
                glossary_pairs=list(cfg.get("glossary") or []),
            )
            content = _chat_completion(
                client=client,
                base_url=base_url,
                api_key=str(cfg["apiKey"]),
                model=str(cfg["model"]),
                messages=messages,
                max_tokens=_estimate_max_tokens(batch),
                temperature=float(cfg["temperature"]),
                top_p=float(cfg["topP"]),
            )
            lines = _parse_line_aligned(content, batch)
            for cue, zh in zip(batch, lines):
                item = dict(cue)
                item["text"] = zh
                out.append(item)
            if on_progress:
                done = min(total, start + len(batch))
                # Local 8–100 → remap overall 70–95 (load band is 0–8).
                local = 8 + int(round(92.0 * done / max(total, 1)))
                payload: dict[str, Any] = {
                    "stage": "translate",
                    "percent": min(100, local),
                    "detail": f"翻译 {done}/{total}",
                    "done": done,
                    "total": total,
                    "backend": "llama",
                }
                on_progress(payload)
    return out
